CREATE VIEW [MQTT].[vwActiveReceivers]
AS

-- Create view
CREATE VIEW MQTT.vwActiveReceivers
AS
SELECT
    rc.ReceiverConfigID,
    rc.Topic,
    rc.QoS,
    b.BrokerName,
    b.HostName,
    b.Port,
    rc.CreatedDate
FROM MQTT.ReceiverConfig rc
INNER JOIN MQTT.Broker b ON rc.BrokerID = b.BrokerID
WHERE rc.IsEnabled = 1

GO

